    pushed to the server over HTTP(S) using only the Python standard library.

    Environment:
        - **KUBEFLOW_TRAINER_SERVER_URL** (`str`, *optional*):
            The URL of the Kubeflow Trainer server to report progress and metrics to. When unset, the callback does
            nothing.
        - **KUBEFLOW_TRAINER_SERVER_TOKEN** (`str`, *optional*):
            Path to a file containing the bearer token used to authenticate with the Kubeflow Trainer server.
    """

    # Minimum number of seconds between two (non-forced) status updates sent to the server.
    _UPDATE_INTERVAL = 10.0
    # Number of seconds a cached authentication token is considered valid before being re-read from disk.
    _TOKEN_TTL = 60.0

    def __init__(self):
        self._initialized = False
        self._metrics = {}
        self._start_time = None
        self._last_update_time = 0.0
        self._cached_token = None
        self._token_read_time = 0.0
        self._ssl_context = None
        self._ssl_context_initialized = False

    def on_train_begin(self, args, state, control, **kwargs):
        if not state.is_world_process_zero:
            return
        self._initialized = True
        self._start_time = time.monotonic()
        self._update_status(progress_percent=0, force=True)

    def on_step_end(self, args, state, control, **kwargs):
        if not self._initialized:
            return

        if state.max_steps and state.max_steps > 0:
            progress = (state.global_step / state.max_steps) * 100
        else:
            progress = 0
        # Never report 100% from ``on_step_end``; completion is reported from ``on_train_end``.
        progress_percent = min(progress, 99)

        estimated_time_remaining = None
        if self._start_time is not None and state.global_step > 0 and state.max_steps and state.max_steps > 0:
            elapsed = time.monotonic() - self._start_time
            time_per_step = elapsed / state.global_step
            estimated_time_remaining = time_per_step * (state.max_steps - state.global_step)

        self._update_status(
            progress_percent=progress_percent,
            estimated_time_remaining=estimated_time_remaining,
            metrics=self._metrics,
        )

    def on_log(self, args, state, control, logs=None, **kwargs):
        if logs is None:
            return
        for key, value in logs.items():
            if isinstance(value, numbers.Number) and not isinstance(value, bool):
                self._metrics[key] = value

    def on_train_end(self, args, state, control, **kwargs):
        self._update_status(progress_percent=100, estimated_time_remaining=0, force=True)

    def _get_ssl_context(self, url):
        if self._ssl_context_initialized:
            return self._ssl_context

        if url.lower().startswith("https"):
            self._ssl_context = ssl.create_default_context()
        else:
            self._ssl_context = None
        self._ssl_context_initialized = True
        return self._ssl_context

    def _get_token(self):
        token_path = os.environ.get("KUBEFLOW_TRAINER_SERVER_TOKEN")
        if not token_path:
            return None

        now = time.monotonic()
        if self._cached_token is not None and (now - self._token_read_time) < self._TOKEN_TTL:
            return self._cached_token

        try:
            with open(token_path) as f:
                self._cached_token = f.read().strip()
            self._token_read_time = now
        except OSError as e:
            logger.warning(f"KubeflowCallback could not read token file {token_path}: {e}")
            return self._cached_token

        return self._cached_token

    def _update_status(self, progress_percent, force=False, estimated_time_remaining=None, metrics=None):
        url = os.environ.get("KUBEFLOW_TRAINER_SERVER_URL")
        if not url:
            return False

        now = time.monotonic()
        if not force and (now - self._last_update_time) < self._UPDATE_INTERVAL:
            return False

        payload = {"progress_percent": progress_percent}
        if estimated_time_remaining is not None:
            payload["estimated_time_remaining"] = estimated_time_remaining
        if metrics:
            payload["metrics"] = metrics

        data = json.dumps(payload).encode("utf-8")
        headers = {"Content-Type": "application/json"}
        token = self._get_token()
        if token:
            headers["Authorization"] = f"Bearer {token}"

        request = urllib.request.Request(url, data=data, headers=headers, method="POST")
        context = self._get_ssl_context(url)

        try:
            if context is not None:
                urllib.request.urlopen(request, context=context)
            else:
                urllib.request.urlopen(request)
        except Exception as e:
            logger.warning(f"KubeflowCallback failed to report status to {url}: {e}")
            return False

        self._last_update_time = now
        return True


